use std::fs

fn find(keys: Vec<int>, k: int) -> int {
    let mut idx: int = -1
    for (i, x) in keys.enumerate() {
        if x == k {
            idx = i
        }
    }
    idx
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut cap: int = 0
    let mut first = true
    let mut keys: Vec<int> = []
    let mut vals: Vec<int> = []
    let mut out: Vec<string> = []
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        if first {
            cap = parts[0].parse::<int>().unwrap_or(1)
            first = false
            continue
        }
        let cmd = parts[0]
        if cmd == "put" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let v = parts[2].parse::<int>().unwrap_or(0)
            let i = find(keys.clone(), k)
            if i >= 0 {
                keys.remove(i)
                vals.remove(i)
            }
            keys.insert(0, k)
            vals.insert(0, v)
            if keys.len() > cap {
                let last = keys.len() - 1
                out.push("evict ${keys[last]}")
                keys.remove(last)
                vals.remove(last)
            }
        } else if cmd == "get" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let i = find(keys.clone(), k)
            if i < 0 {
                out.push("-1")
            } else {
                let v = vals[i]
                keys.remove(i)
                vals.remove(i)
                keys.insert(0, k)
                vals.insert(0, v)
                out.push("${v}")
            }
        } else if cmd == "keys" {
            if keys.len() == 0 {
                out.push("<empty>")
            } else {
                let strs: Vec<string> = keys.map(|x| "${x}").collect()
                out.push(strs.join(" "))
            }
        }
    }
    for o in out {
        println(o)
    }
}

